item.content:encoded:
/* Global Definitions */
.post-header { 
	padding: 3% 10%;
}
.post-header .post-title a:hover, .post-header .post-title a:focus {
	color: #24778d;
}
.single .post-content { 
	padding: 5%;
}

.posts-navigation a:hover, .posts-navigation a:focus {
	background: #24778d;
}

.posts .post-content {
	padding: 10% 10% 0;
}

.posts .post-content .more-link {
	margin-bottom: 1.1em;
}

.post-container {
	padding: 0 1.5% 0;
	margin-bottom: 4.5%;
}

.home .featured-media {
height: 230px;
overflow: hidden;
}

.table-responsive td {
		border: 0;
}

/* hide not needed elements */
.nocomments,
.sfsiaftrpstwpr {
	display: none;
}

body.single .content.center,
.section-inner,
.section-inner.content {
	width: 1140px;
}

body a,
.footer a,
.footer a:hover,
.footer a:focus {
	color: #24778d;
}

.footer .medium-padding {
    padding: 20px 0;
}

.header {
  height: 250px;
	transition: none;
}


/* Main Navigation */
@media (max-width: 600px) {
	.nav-toggle {
		float:right;
		margin-right: 20px;
		color: white;
		opacity: 1;
 }
	.main-navigation {
		clear:both;
	}
}


.main-navigation li:before {
	display: none;
}
.main-navigation a {
	transition: color .5s ease, background .5s ease;
}

li.current-menu-parent > a,
li.current-menu-item > a,
#primary-menu a:hover {
	background-color: #243064;
	transition: all .5s ease;
	color: #fff;
}

#primary-menu > li.current-menu-item a:after {
	border-top-color: #fff;
}

/* deaktiviere Suche */
.search-icon { display: none; }

/* Footer */
.credits {display: none;}
#footer .menu-item {
    display: inline-block;
    margin-left: 24px;
}

#footer .row {
	margin: 0 auto;
}
.widget-content ul li:before {
	display: none;
}

/* Sponsor Page */
#sponsoren a {
    display: block;
    margin-bottom: 24px;
}
#sponsoren a > img {
	border: 1px solid #ccc;
	padding: 8px;
	box-shadow: 0 0 0;
	transition: box-shadow .3s ease;
	width: 100%;
}
#sponsoren a:hover > img {
	box-shadow: 3px 3px 3px #ccc;
	transition: box-shadow .3s ease;
}
#sponsoren .row {
   display: flex;
   flex-wrap: wrap;
}
#sponsoren [class*='col-'] {
   display: flex;
   flex-direction: column;
   justify-content: space-evenly;
}

/* Responsive Google Calender */
.responsiveMaps {
  position: relative;
  padding-bottom: 56%;
  height: 0;
  overflow: hidden;
}

.responsiveMaps iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}


.responsiveContainer iframe,
.responsiveContainer object,
.responsiveContainer embed {
  width: 100%;
	padding: 0 1px;
}
.responsiveContainer iframe {
	min-height: 1946px;
}
.view-container-border {
	padding: 0;
}
.bubble {
	left: 0 !important;
    width: 100% !important;
}

/*Tabby */
.responsive-tabs .responsive-tabs__panel {
  border-left: 0 !important;
  border-right: 0 !important;
  border-top: 1px solid #ddd !important;
  padding: 20px 0 !important;
}
.responsive-tabs .responsive-tabs__list__item--active, 
.responsive-tabs__list__item:hover {
	background-color: #243064 !important;
	transition: all .5s ease;
	color: #fff !important;
	font-weight: bold !important;
}

@media (max-width: 767px) {
.responsive-tabs .responsive-tabs__heading {
	padding: 17px 10px !important;
}
	.responsive-tabs .responsive-tabs__heading:after {
	top: calc(50% - 3px) !important
	}
}

/*Remove comment function and post footer container */
.post-comments,
.comment-respond,
.post-meta-container {
 display: none !important;
}

